record.field:
for record in self:
    if record.product_id and record.order_partner_id:
        ref_record = self.env['x_external_reference'].search([
            ('x_ext_ref_product_id', '=', record.product_id.product_tmpl_id.id),
            ('x_ext_ref_partner_id', '=', record.order_partner_id.commercial_partner_id.id)
        ], limit=1)
        record['x_external_reference_id'] = ref_record.id
